  function interpolate(s, obj) {
    if (!s || typeof s !== 'string') return s;
    var preparedStr = prepareMock(s);
    if (!obj || typeof obj !== 'object') return preparedStr;
    var preparedObj = prepareMockObj(obj);
    return replace(preparedStr, preparedObj);
  }

  var globalEnvironmentVariables = options.globalEnvironmentVariables;
  var collectionVariables = options.collectionVariables;
  var envVars = options.envVars;
  var folderVariables = options.folderVariables;
  var requestVariables = options.requestVariables;
  var runtimeVariables = options.runtimeVariables;
  var processEnvVars = options.processEnvVars;
  var promptVariables = options.promptVariables;
